<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/../includes/kitchen.php';require_once __DIR__.'/../includes/pos.php';require_once __DIR__.'/../config/database.php';
$checks=0;function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;echo "PASS: $label\n";}
function rejected(callable $fn,int $status,string $label):void{try{$fn();}catch(OrderError $error){check($error->status===$status,$label);return;}throw new RuntimeException('FAIL: accepted '.$label);}
$db=quvo_db();try{
$db->beginTransaction();$tag=bin2hex(random_bytes(6));$actor=['staff_id'=>(int)$db->query("SELECT TOP 1 s.staff_id FROM dbo.staff_users s JOIN dbo.roles r ON r.role_id=s.role_id WHERE s.is_active=1 AND LOWER(r.role_name) IN ('staff','admin')")->fetchColumn(),'role'=>'staff'];
$q=$db->prepare("INSERT dbo.menu_items(item_name,category,price,is_available) OUTPUT INSERTED.menu_item_id VALUES(?,?,10,1)");$q->execute(['Kitchen food '.$tag,'food']);$food=(int)$q->fetchColumn();$q->closeCursor();$q->execute(['Kitchen drink '.$tag,'coffee']);$drink=(int)$q->fetchColumn();$q->closeCursor();
$make=function(array $ids)use($db,$actor){return pos_submit($db,$actor,['submission_key'=>sprintf('%s-%s-4%s-8%s-%s',bin2hex(random_bytes(4)),bin2hex(random_bytes(2)),bin2hex(random_bytes(2))[0].bin2hex(random_bytes(1)),bin2hex(random_bytes(2))[0].bin2hex(random_bytes(1)),bin2hex(random_bytes(6))),'customer_name'=>'Kitchen SQL test','expected_total'=>count($ids)*10,'payment_method'=>'Cash','amount_received'=>count($ids)*10,'items'=>array_map(fn($id)=>['menu_id'=>$id,'quantity'=>1,'notes'=>'<No sauce>'],$ids)])['order'];};
$foodOrder=$make([$food]);$mixed=$make([$food,$drink]);$drinkOrder=$make([$drink]);
$ticket=kitchen_get($db,(int)$mixed['order_id']);check(count($ticket['items'])===1&&$ticket['items'][0]['category']==='food','mixed ticket contains food only');check($ticket['items'][0]['notes']==='<No sauce>','food notes preserved');check(!isset($ticket['payment_reference'],$ticket['contact_snapshot']),'kitchen response omits private payment/contact details');
rejected(fn()=>kitchen_ready($db,[...$actor,'role'=>'barista'],(int)$mixed['order_id']),403,'unauthorized role rejected');rejected(fn()=>kitchen_get($db,(int)$drinkOrder['order_id']),404,'drink-only order excluded');rejected(fn()=>kitchen_list($db,-1),422,'invalid pagination rejected');
$ready=kitchen_ready($db,$actor,(int)$mixed['order_id']);check($ready['order']['status']==='ready'&&$ready['order']['order_status']==='preparing','mixed food readiness does not mark drinks ready');check(orders_get($db,(int)$mixed['order_id'])['kitchen_ready_at']!==null,'cashier order response exposes saved food readiness');check(kitchen_ready($db,$actor,(int)$mixed['order_id'])['replayed'],'ready retry is idempotent');check((int)$db->query('SELECT COUNT(*) FROM dbo.kitchen_ticket_readiness WHERE order_id='.(int)$mixed['order_id'])->fetchColumn()===1,'one readiness record per order');
$ready=kitchen_ready($db,$actor,(int)$foodOrder['order_id']);check($ready['order']['order_status']==='ready','food-only order advances to ready');orders_status($db,$actor['staff_id'],(int)$foodOrder['order_id'],'served');rejected(fn()=>kitchen_get($db,(int)$foodOrder['order_id']),409,'served order leaves kitchen queue');
$q=$db->prepare("INSERT dbo.cafe_tables(table_code,table_name,area) OUTPUT INSERTED.table_id VALUES(?,'Kitchen test','indoor')");$q->execute(['kt-'.$tag]);$table=(int)$q->fetchColumn();$q->closeCursor();$q=$db->prepare("INSERT dbo.customer_sessions(table_id,guest_name,guest_token_hash,status) OUTPUT INSERTED.session_id VALUES(?,'Kitchen test',CONVERT(binary(32),?,2),'active')");$q->execute([$table,hash('sha256',$tag)]);$session=(int)$q->fetchColumn();$q->closeCursor();
$q=$db->prepare("INSERT dbo.customer_accounts(full_name,email,contact_number,password_hash) OUTPUT INSERTED.customer_account_id VALUES('Kitchen test',?,'09123456789','test-only')");$q->execute([$tag.'@kitchen.test']);$account=(int)$q->fetchColumn();$q->closeCursor();
foreach(['dine_in','online'] as $source){
 $q=$db->prepare("INSERT dbo.orders(order_source,session_id,customer_account_id,customer_name,submission_key,submission_hash,total_amount,preferred_payment_method) OUTPUT INSERTED.order_id VALUES(?,?,?,'Kitchen test',NEWID(),CONVERT(binary(32),?,2),10,?)");$q->execute([$source,$source==='dine_in'?$session:null,$source==='online'?$account:null,hash('sha256',$source),$source==='online'?'GCash':null]);$id=(int)$q->fetchColumn();$q->closeCursor();
 $db->prepare("INSERT dbo.order_items(order_id,line_number,menu_item_id,item_name,category,unit_price,quantity,customization_json,notes) VALUES(?,1,?,'Kitchen food','food',10,1,'{}','No sauce')")->execute([$id,$food]);
 rejected(fn()=>kitchen_get($db,$id),409,$source.' unpaid order excluded');orders_pay($db,$actor['staff_id'],$id,['payment_method'=>$source==='online'?'GCash':'Cash','amount_received'=>'10.00']);check(kitchen_get($db,$id)['order_source']===$source,$source.' paid food appears');
}
$queue=kitchen_list($db)['orders'];check(!in_array($drinkOrder['order_id'],array_column($queue,'order_id'),true),'drink-only order absent from queue');check(in_array($mixed['order_id'],array_column($queue,'order_id'),true),'mixed ready food remains until full order served');echo "$checks kitchen SQL checks passed.\n";
}finally{if($db->inTransaction())$db->rollBack();echo "Kitchen test fixtures rolled back.\n";}
